// One calendar entry per occurrence. Recurring events carry every date in childEvents,
// so expand them; an event with no start time cannot be scheduled, so drop it.
const out = [];
for (const { json: e } of $input.all()) {
  const dates = (e.childEvents && e.childEvents.length)
    ? e.childEvents.map(c => ({ start: c.utcStartDate, end: c.utcEndDate, url: c.url }))
    : [{ start: e.utcStartDate, end: e.utcEndDate, url: e.url }];

  for (const d of dates) {
    if (!d.start) continue;
    const end = d.end || new Date(new Date(d.start).getTime() + 2 * 3600 * 1000).toISOString();
    out.push({ json: {
      summary:     e.name,
      start:       d.start,
      end,
      location:    e.address || e.location?.name || '',
      description: [e.description, d.url || e.url].filter(Boolean).join('\n\n'),
    }});
  }
}
return out;
